-- MyNclex bank gap-fill batch 08 — prioritisation, triage and clinical judgement under load
-- Batch: gapfill-20260728
-- Item block: NCLEX_*_531001 – NCLEX_*_531055 (55 items)
-- Focus: Safe and Effective Care Environment / Management of Care (44 items),
--        Safety and Infection Control (5), Reduction of Risk Potential (4),
--        Pharmacological and Parenteral Therapies (2).
-- Rule stack taught: acute beats chronic; fresh post-op under 12 hours beats
--        other clients; unstable beats stable; the four always-unstable states
--        (haemorrhage, temperature above 40.5 C, hypoglycaemia, pulseless or
--        breathless); organ hierarchy (brain, lung, heart, liver, kidney,
--        pancreas) as tie-breaker; the modifying phrase decides; mass casualty
--        triage reverses ordinary priority.

INSERT INTO nclex_bank_items (
  item_id, question_type, stem, rationale, content, correct,
  client_needs_category, client_needs_subcategory, nursing_subject, body_system,
  topic, subtopic, difficulty, difficulty_source, bloom_level, tags,
  marks, is_published, is_builder_visible, is_free_sample, cat_pool, batch_id
) VALUES
('NCLEX_MCQ_531001', 'MCQ',
 'A nurse arrives on a medical ward and receives handover on four clients. Which client should the nurse assess FIRST?',
 'Priority setting begins by separating acute from chronic. A new or newly changed presentation has an unknown cause and an unknown trajectory, so it must be evaluated before a long-standing problem that has already been assessed and is being managed. New-onset breathlessness in heart failure may signal acute decompensation or pulmonary oedema. The chronic cough, the long-standing joint pain and the unchanged glucose are all stable findings that can safely wait.',
 '{"options":[{"id":"A","text":"A client with chronic obstructive pulmonary disease who has had a productive cough for three years"},{"id":"B","text":"A client with heart failure who reports shortness of breath that began 20 minutes ago"},{"id":"C","text":"A client with osteoarthritis who reports long-standing knee pain rated 6 out of 10"},{"id":"D","text":"A client with type 2 diabetes mellitus whose blood glucose has been 9.4 mmol/L for two days"}]}'::jsonb,
 '{"answer":"B","feedback":{"A":"Incorrect. A cough present for three years is chronic and unchanged, so it does not outrank an acute change.","B":"Correct. Breathlessness that began 20 minutes ago is an acute change of unknown cause and outranks every chronic finding here.","C":"Incorrect. Long-standing joint pain is an expected symptom of the known diagnosis and can be addressed after the acute client is seen.","D":"Incorrect. A glucose unchanged over two days is a stable finding rather than an acute change."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem',
 'Prioritisation', 'Acute beats chronic',
 'Very easy', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_MCQ_531002', 'MCQ',
 'A nurse on a surgical ward is deciding the order of the assessment round. All four clients currently have observations within their usual range. Which client should the nurse assess FIRST?',
 'A client within 12 hours of surgery under general anaesthesia is treated as unstable regardless of how reassuring the recorded observations look, because airway patency, circulating volume and wound bleeding can all change within minutes. The fresh post-operative client therefore outranks other medical and surgical clients. Surgery three days ago, a two-day admission for cellulitis and a lesion excised under local anaesthesia are all stable markers: time has passed, the assessment is unchanged and the anaesthetic did not depress airway reflexes.',
 '{"options":[{"id":"A","text":"A client who returned from theatre four hours ago after abdominal surgery under general anaesthesia"},{"id":"B","text":"A client three days after cholecystectomy who is walking in the corridor"},{"id":"C","text":"A client admitted two days ago with cellulitis who is receiving intravenous antibiotics"},{"id":"D","text":"A client who had a skin lesion excised under local anaesthesia yesterday"}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. General anaesthesia within the last 12 hours is an unstable marker, so the fresh post-operative client is assessed first.","B":"Incorrect. Post-operative day three with independent mobility is a stable marker.","C":"Incorrect. An admission of more than 24 hours with treatment already under way is a stable marker.","D":"Incorrect. Local anaesthesia does not depress airway reflexes or circulation, so this client is stable."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem',
 'Prioritisation', 'Fresh post-operative client',
 'Medium', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_MAT_531003', 'MATRIX',
 'A nurse reviews the caseload at the start of a shift. Classify each client as stable or unstable using the standard stability markers.',
 'Stable markers are chronic, unchanged assessment, expected symptoms of the known diagnosis, post-operative beyond 12 hours, local or regional anaesthesia, admitted more than 24 hours and ready for discharge. Unstable markers are acute, newly admitted, a changed or changing assessment, symptoms that are unexpected for the diagnosis, and general anaesthesia within the last 12 hours. Four states are always unstable even when they were anticipated: haemorrhage, temperature above 40.5 degrees Celsius, hypoglycaemia, and pulseless or breathless.',
 '{"rows":[{"id":"r1","text":"A client 30 hours after knee arthroscopy performed under regional anaesthesia whose assessment is unchanged"},{"id":"r2","text":"A client admitted 20 minutes ago with new-onset atrial fibrillation"},{"id":"r3","text":"A client with terminal lung cancer whose expected pain is unchanged and controlled"},{"id":"r4","text":"A client two hours after thyroidectomy performed under general anaesthesia"},{"id":"r5","text":"A client whose capillary blood glucose is 2.4 mmol/L"},{"id":"r6","text":"A client with pneumonia who has a productive cough on day three of antibiotics"}],"columns":[{"id":"c1","text":"Stable"},{"id":"c2","text":"Unstable"}],"row_label":"Client"}'::jsonb,
 '{"cells":{"r1":"c1","r2":"c2","r3":"c1","r4":"c2","r5":"c2","r6":"c1"},"feedback":{}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem',
 'Prioritisation', 'Stable and unstable markers',
 'Medium', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_MCQ_531004', 'MCQ',
 'Four clients on a surgical ward have some degree of bleeding. Which client requires the immediate attention of the nurse?',
 'Haemorrhage is not the same as ordinary bleeding. Ordinary bleeding is small in volume, visible, self-limiting and expected for the situation. Haemorrhage is rapid or concealed loss that will compromise perfusion if it continues, and it belongs to the group of states that are always treated as unstable. Repeated swallowing with pallor after tonsillectomy is the classic sign of concealed bleeding at the tonsillar bed, because the blood tracks down the pharynx instead of appearing outside the body.',
 '{"options":[{"id":"A","text":"A client having a menstrual period who has changed one pad in four hours"},{"id":"B","text":"A client whose wound drain has collected 30 mL of serosanguineous fluid over eight hours"},{"id":"C","text":"A client whose nosebleed stopped after five minutes of direct pressure"},{"id":"D","text":"A client six hours after tonsillectomy who is swallowing repeatedly and is pale"}]}'::jsonb,
 '{"answer":"D","feedback":{"A":"Incorrect. One pad in four hours is within normal menstrual loss.","B":"Incorrect. Thirty millilitres of serosanguineous drainage over eight hours is expected post-operative drainage, not haemorrhage.","C":"Incorrect. Bleeding that has stopped with simple pressure is ordinary bleeding and is self-limiting.","D":"Correct. Repeated swallowing with pallor after tonsillectomy signals concealed haemorrhage, which is always treated as unstable."}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential',
 'Medical-Surgical', 'Multisystem',
 'Haemorrhage recognition', 'Concealed bleeding',
 'Hard', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_SATA_531005', 'SATA',
 'Some client states are treated as unstable even when they were fully anticipated. Which findings must the nurse treat as unstable regardless of whether they were expected? Select all that apply.',
 'Most expected findings are stable findings, but four states break that rule because each will kill or cause irreversible harm if it continues: haemorrhage, a temperature above 40.5 degrees Celsius or 105 degrees Fahrenheit, hypoglycaemia, and being pulseless or breathless. Anticipating a state does not slow its physiology. Expected incisional pain, an unchanged chronic wound and a productive cough during treatment for pneumonia are all stable because they are consistent with the known diagnosis and are not immediately harmful.',
 '{"options":[{"id":"A","text":"Haemorrhage from a surgical wound"},{"id":"B","text":"A temperature of 41.0 degrees Celsius"},{"id":"C","text":"A capillary blood glucose of 2.2 mmol/L"},{"id":"D","text":"Absence of a palpable pulse"},{"id":"E","text":"Incisional pain of 6 out of 10 on the first post-operative day"},{"id":"F","text":"A chronic pressure injury that is unchanged"},{"id":"G","text":"A productive cough on day three of treatment for pneumonia"}]}'::jsonb,
 '{"answers":["A","B","C","D"],"feedback":{"A":"Correct. Haemorrhage is always unstable because continued loss compromises perfusion.","B":"Correct. A temperature above 40.5 degrees Celsius risks cellular and neurological injury and is always unstable.","C":"Correct. Hypoglycaemia deprives the brain of its only fuel and is always unstable.","D":"Correct. A pulseless client is always unstable and requires resuscitation.","E":"Incorrect. Incisional pain on day one is an expected symptom of the known situation and is a stable finding.","F":"Incorrect. A chronic unchanged wound is a stable marker.","G":"Incorrect. A productive cough during treatment for pneumonia is an expected symptom of the diagnosis."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem',
 'Prioritisation', 'Always unstable states',
 'Medium', 'CURATOR_LABEL', 'Understand', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_MCQ_531006', 'MCQ',
 'Four clients call for the nurse at the same moment. Which client should the nurse attend to FIRST?',
 'Hypoglycaemia is one of the states that is always unstable. The brain has no fuel store and relies on a continuous supply of glucose, so untreated hypoglycaemia produces seizures, coma and permanent injury within minutes. A moderate fever during treatment, a request for prescribed analgesia and a cannula due for routine change are all either expected findings or time-flexible tasks.',
 '{"options":[{"id":"A","text":"A client who is requesting the prescribed as-required analgesia"},{"id":"B","text":"A client whose temperature is 38.4 degrees Celsius on the second day of antibiotics"},{"id":"C","text":"A client whose capillary blood glucose is 2.4 mmol/L and who is sweating and shaky"},{"id":"D","text":"A client whose intravenous cannula is due to be changed today"}]}'::jsonb,
 '{"answer":"C","feedback":{"A":"Incorrect. Pain relief matters, but it can be given after the hypoglycaemic client is treated.","B":"Incorrect. A fever of 38.4 degrees Celsius during antibiotic treatment is an expected finding and is well below the 40.5 degree threshold.","C":"Correct. Hypoglycaemia is always unstable and threatens the brain within minutes.","D":"Incorrect. A routine cannula change is a time-flexible task."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem',
 'Prioritisation', 'Hypoglycaemia as an always-unstable state',
 'Very easy', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_MCQ_531007', 'MCQ',
 'A nurse enters a room on a general ward and finds a client who is unresponsive, is not breathing normally and has no carotid pulse. Which action is the PRIORITY?',
 'Inside the hospital, a pulseless and breathless client is the highest priority of all and receives immediate resuscitation. Survival falls with every minute that compressions are delayed, so summoning the resuscitation team and starting chest compressions happen together and before any diagnostic step. Recording an electrocardiogram, checking a glucose or repositioning the client all delay circulation to the brain and heart and none of them changes the immediate management.',
 '{"options":[{"id":"A","text":"Place the client in the recovery position"},{"id":"B","text":"Obtain a 12-lead electrocardiogram"},{"id":"C","text":"Check the capillary blood glucose"},{"id":"D","text":"Call the resuscitation team and begin chest compressions"}]}'::jsonb,
 '{"answer":"D","feedback":{"A":"Incorrect. The recovery position is for a client who is breathing and has a pulse.","B":"Incorrect. An electrocardiogram delays compressions and does not alter the immediate response to cardiac arrest.","C":"Incorrect. A glucose measurement is a diagnostic step that cannot precede circulation.","D":"Correct. A pulseless, breathless client needs the resuscitation team and immediate chest compressions."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Medical-Surgical', 'Multisystem',
 'Deterioration and escalation', 'In-hospital cardiac arrest',
 'Easy', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_MCQ_531008', 'MCQ',
 'Four clients are admitted to a medical ward at the same time from the emergency department. Each is newly diagnosed and each has an assessment that has changed in the last hour. Which client should the nurse assess FIRST?',
 'When the higher rules tie, the organ hierarchy breaks the tie: brain, then lung, heart, liver, kidney and pancreas. All four clients here are acute, newly admitted and changing, so acuity does not separate them. The organ named decides, and the brain sits at the top because neurological tissue tolerates insult for the shortest time and the damage is the least reversible. Rising intracranial pressure from a subdural haematoma can progress to herniation within minutes.',
 '{"options":[{"id":"A","text":"A client newly diagnosed with acute pancreatitis who has developed epigastric pain"},{"id":"B","text":"A client newly diagnosed with acute kidney injury who has become oliguric"},{"id":"C","text":"A client newly diagnosed with a subdural haematoma who has become confused"},{"id":"D","text":"A client newly diagnosed with acute hepatitis who has developed jaundice"}]}'::jsonb,
 '{"answer":"C","feedback":{"A":"Incorrect. The pancreas sits lowest in the organ hierarchy, so this client is assessed last of the four.","B":"Incorrect. The kidney sits below the brain in the hierarchy, and oliguria harms more slowly than rising intracranial pressure.","C":"Correct. When acuity ties, the organ hierarchy decides and the brain ranks highest.","D":"Incorrect. The liver ranks below the brain, and jaundice is a slower process than neurological deterioration."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem',
 'Prioritisation', 'Organ hierarchy tie-breaker',
 'Hard', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_MCQ_531009', 'MCQ',
 'A nurse beginning a night shift on a trauma and orthopaedic ward reviews the caseload. Which client should the nurse assess FIRST?',
 'The diagnosis names the category; the modifying phrase that follows it decides the priority. Here the two most alarming diagnoses, myocardial infarction and metastatic bone cancer, are followed by modifiers that describe stability: pain free and awaiting discharge, and usual pain relieved by prescribed analgesia. The fractured wrist sounds trivial until the modifier is read: numbness and cool fingertips beginning 20 minutes ago describe acute neurovascular compromise beneath a cast, which threatens the limb and is time-critical.',
 '{"options":[{"id":"A","text":"A client admitted with a myocardial infarction three days ago who is pain free and awaiting discharge medicines"},{"id":"B","text":"A client with a fractured wrist in a plaster cast who reports numbness and cool fingertips that began 20 minutes ago"},{"id":"C","text":"A client with metastatic bone cancer whose pain is at the usual level and is relieved by the prescribed analgesia"},{"id":"D","text":"A client with newly diagnosed epilepsy whose observations have been unchanged since admission yesterday"}]}'::jsonb,
 '{"answer":"B","feedback":{"A":"Incorrect. A serious diagnosis followed by pain free and awaiting discharge describes a stable client.","B":"Correct. The modifying detail describes acute neurovascular compromise under a cast, which is limb-threatening and outranks the alarming diagnoses.","C":"Incorrect. Pain at the usual level relieved by analgesia is an expected symptom of the known diagnosis.","D":"Incorrect. Unchanged observations since yesterday is a stable marker despite the new diagnosis."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem',
 'Prioritisation', 'The modifying phrase decides',
 'Very hard', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_MCQ_531010', 'MCQ',
 'Four clients are waiting to be seen in a walk-in clinic. Which client should the nurse see FIRST?',
 'Age and sex are almost never priority criteria on their own, and an examination question that offers an older or a very young client is usually offering a distractor. What decides here is the clinical modifier. Speaking in single words is a marker of severe airflow obstruction and impending respiratory failure in asthma. An oxygen saturation of 95 per cent on room air, uncomplicated recovery after appendicectomy and a low-grade temperature with a urinary tract infection are all expected findings.',
 '{"options":[{"id":"A","text":"An 82-year-old client with pneumonia whose oxygen saturation is 95 per cent on room air"},{"id":"B","text":"A 19-year-old client two days after appendicectomy who is eating and drinking normally"},{"id":"C","text":"A 45-year-old client with asthma who can now speak only in single words"},{"id":"D","text":"A 70-year-old client with a urinary tract infection whose temperature is 37.8 degrees Celsius"}]}'::jsonb,
 '{"answer":"C","feedback":{"A":"Incorrect. Age alone does not create priority, and a saturation of 95 per cent on room air is a reassuring finding.","B":"Incorrect. Eating and drinking normally two days after surgery is a stable marker.","C":"Correct. Speaking in single words indicates severe airflow obstruction and impending respiratory failure.","D":"Incorrect. A temperature of 37.8 degrees Celsius is an expected symptom of a urinary tract infection, and age does not raise the priority."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem',
 'Prioritisation', 'Age and sex as distractors',
 'Medium', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728');

INSERT INTO nclex_bank_items (
  item_id, question_type, stem, rationale, content, correct,
  client_needs_category, client_needs_subcategory, nursing_subject, body_system,
  topic, subtopic, difficulty, difficulty_source, bloom_level, tags,
  marks, is_published, is_builder_visible, is_free_sample, cat_pool, batch_id
) VALUES
('NCLEX_SATA_531011', 'SATA',
 'Which descriptions identify a client the nurse may regard as stable? Select all that apply.',
 'The stable list is short and worth memorising: chronic, unchanged assessment, expected symptoms of the known diagnosis, post-operative beyond 12 hours, local or regional anaesthesia, admitted more than 24 hours, and ready for discharge. Anything newly admitted, acutely changed or unexpected for the diagnosis belongs on the unstable side, because the nurse does not yet know where the change is heading.',
 '{"options":[{"id":"A","text":"Three days after surgery with an assessment unchanged for 24 hours"},{"id":"B","text":"Experiencing the symptoms that are expected with the known diagnosis"},{"id":"C","text":"Admitted 20 minutes ago through the emergency department"},{"id":"D","text":"Six hours after a procedure performed under local anaesthesia with an unchanged assessment"},{"id":"E","text":"Reporting a symptom that was not expected with the known diagnosis"},{"id":"F","text":"Medically fit and waiting for transport home"}]}'::jsonb,
 '{"answers":["A","B","D","F"],"feedback":{"A":"Correct. Post-operative beyond 12 hours with an unchanged assessment is a stable marker.","B":"Correct. Symptoms that match the known diagnosis are expected and therefore stable.","C":"Incorrect. A newly admitted client is unstable because no baseline or trajectory has been established.","D":"Correct. Local anaesthesia does not depress airway reflexes or circulation, and the assessment is unchanged.","E":"Incorrect. An unexpected symptom is an unstable marker because its cause is unknown.","F":"Correct. Ready for discharge is a stable marker."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem',
 'Prioritisation', 'Recognising the stable client',
 'Easy', 'CURATOR_LABEL', 'Understand', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_MCQ_531012', 'MCQ',
 'A nurse is planning an assessment round on a surgical ward. Which client should the nurse assess LAST?',
 'Prioritising also runs in the other direction. Deciding who can safely wait is the same reasoning applied in reverse, and it frees the nurse to spend time where the risk is. The client 30 hours after surgery under regional anaesthesia with an unchanged assessment and a completed discharge plan carries every stable marker at once. An admission of one hour with undiagnosed pain, a falling blood pressure and repeated vomiting after general anaesthesia are all changing situations.',
 '{"options":[{"id":"A","text":"A client whose blood pressure fell to 92/54 mmHg on the last set of observations"},{"id":"B","text":"A client admitted one hour ago with abdominal pain of unknown cause"},{"id":"C","text":"A client 30 hours after hernia repair under regional anaesthesia whose assessment is unchanged and who is waiting for discharge medicines"},{"id":"D","text":"A client three hours after general anaesthesia who has vomited twice"}]}'::jsonb,
 '{"answer":"C","feedback":{"A":"Incorrect. A falling blood pressure is a changing assessment and cannot be left until last.","B":"Incorrect. A new admission with undiagnosed pain is unstable and must be seen early.","C":"Correct. Post-operative beyond 12 hours, regional anaesthesia, unchanged assessment and ready for discharge are four stable markers together.","D":"Incorrect. Repeated vomiting within 12 hours of general anaesthesia risks aspiration and dehydration."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem',
 'Prioritisation', 'Deciding who can wait',
 'Easy', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_SATA_531013', 'SATA',
 'A nurse is handing over to the incoming shift. Which clients should be reported as priorities for the first hour of the next shift? Select all that apply.',
 'Handover is a prioritisation tool, not a recitation of the caseload. The incoming nurse needs to know which clients are changing, which are within the vulnerable early post-anaesthetic window and which have an outstanding result that may change management. Clients whose care is routine, complete or planned for the following day do not compete for the first hour.',
 '{"options":[{"id":"A","text":"A client whose oxygen requirement has risen from 2 to 6 litres per minute during the shift"},{"id":"B","text":"A client who is being discharged tomorrow morning"},{"id":"C","text":"A client who returned from theatre one hour ago after general anaesthesia"},{"id":"D","text":"A client with a chronic leg ulcer whose dressing was changed this morning"},{"id":"E","text":"A client with a temperature of 38.8 degrees Celsius whose blood culture result is pending"},{"id":"F","text":"A client who declined a bath and will be offered one tomorrow"}]}'::jsonb,
 '{"answers":["A","C","E"],"feedback":{"A":"Correct. A tripling of the oxygen requirement is a changing assessment and must be seen early.","B":"Incorrect. A planned discharge tomorrow is a stable situation.","C":"Correct. General anaesthesia within the last 12 hours is an unstable marker.","D":"Incorrect. A chronic ulcer already dressed this morning is unchanged and routine.","E":"Correct. Fever with a pending culture may need antibiotics changed urgently, so it belongs in the first hour.","F":"Incorrect. A deferred bath is a comfort task with no time pressure."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem',
 'Handover', 'Prioritising the handover report',
 'Medium', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_SATA_531014', 'SATA',
 'A charge nurse is allocating clients on a medical ward. Which clients must be assigned to the registered nurse rather than to the licensed practical nurse? Select all that apply.',
 'The registered nurse keeps the parts of care that require assessment, judgement and evaluation: the first assessment of a new client, the reassessment after a change of condition, and the administration of blood components. Tasks that follow an established plan on a client whose condition is predictable, such as a routine dressing on a chronic wound, reinforcement of teaching already given or a routine oral medicine round, may be assigned to a licensed practical nurse.',
 '{"options":[{"id":"A","text":"A client admitted 20 minutes ago who has not yet had an admission assessment"},{"id":"B","text":"A client for whom a unit of packed red cells is to be commenced"},{"id":"C","text":"A client with a stable chronic leg ulcer requiring a routine dressing change"},{"id":"D","text":"A client whose condition changed one hour ago and who now needs a full reassessment"},{"id":"E","text":"A client three days after surgery who needs reinforcement of discharge teaching already given"},{"id":"F","text":"A client who requires a routine oral medicine round"}]}'::jsonb,
 '{"answers":["A","B","D"],"feedback":{"A":"Correct. The initial assessment of a new client is a registered nurse responsibility.","B":"Correct. Commencing a blood transfusion requires registered nurse assessment and verification.","C":"Incorrect. A routine dressing on a stable chronic wound may be assigned to a licensed practical nurse.","D":"Correct. Reassessment after a change of condition requires registered nurse judgement.","E":"Incorrect. Reinforcing teaching that has already been given is within the licensed practical nurse scope.","F":"Incorrect. Routine oral medicines for stable clients may be assigned to a licensed practical nurse."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem',
 'Assignment', 'Registered nurse only responsibilities',
 'Medium', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_SATA_531015', 'SATA',
 'A registered nurse is supervising a licensed practical nurse on a medical ward. Which observed actions require the registered nurse to intervene? Select all that apply.',
 'Supervision means watching for actions that fall outside the assigned scope and correcting them before harm occurs. The initial admission assessment, the administration of blood components and the disclosure of results the medical team has not yet discussed with the client all sit outside the licensed practical nurse role. Reinforcing teaching already delivered, recording and reporting observations on a stable client and changing a simple dry dressing are all appropriately within scope and need no intervention.',
 '{"options":[{"id":"A","text":"The licensed practical nurse begins the admission assessment of a client who arrived 10 minutes ago"},{"id":"B","text":"The licensed practical nurse reinforces teaching about a low-salt diet that the registered nurse has already given"},{"id":"C","text":"The licensed practical nurse hangs a unit of packed red cells"},{"id":"D","text":"The licensed practical nurse records the observations of a stable client and reports them to the registered nurse"},{"id":"E","text":"The licensed practical nurse tells a relative the result of a scan that has not yet been discussed with the client"},{"id":"F","text":"The licensed practical nurse changes a dry dressing on a healing wound"}]}'::jsonb,
 '{"answers":["A","C","E"],"feedback":{"A":"Correct. The initial assessment cannot be delegated, so the registered nurse must intervene.","B":"Incorrect. Reinforcing teaching already given is within scope and requires no intervention.","C":"Correct. Blood component administration is a registered nurse responsibility.","D":"Incorrect. Recording and reporting observations on a stable client is appropriate.","E":"Correct. Disclosing results before the client has been informed breaches confidentiality and the duty of the medical team, so the registered nurse must intervene.","F":"Incorrect. A simple dry dressing on a healing wound is within scope."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem',
 'Supervision', 'When to intervene',
 'Medium', 'CURATOR_LABEL', 'Evaluate', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_DO_531016', 'DRAG_ORDER',
 'After handover the nurse must assess four clients. Place the clients in the order in which the nurse should see them, from first to last.',
 'Work down the rule stack in order. The client two hours after craniotomy has an acute neurological change, and the brain is the highest organ in the hierarchy, so this client comes first. The newly admitted client with a rising respiratory rate is acute and changing but the lung sits below the brain. The client after spinal anaesthesia is within 12 hours of surgery but the assessment is unchanged and the anaesthetic was regional, so the risk is lower. A routine dressing change on a client admitted three days ago carries no time pressure at all.',
 '{"slots":[{"id":"s1","target_text":"1st"},{"id":"s2","target_text":"2nd"},{"id":"s3","target_text":"3rd"},{"id":"s4","target_text":"4th"}],"tokens":[{"id":"t1","text":"A client two hours after craniotomy whose speech has become slurred in the last 10 minutes"},{"id":"t2","text":"A client three hours after knee replacement under spinal anaesthesia whose assessment is unchanged"},{"id":"t3","text":"A client with pneumonia admitted 30 minutes ago whose respiratory rate has risen to 30 breaths per minute"},{"id":"t4","text":"A client with chronic kidney disease admitted three days ago who is due for a routine dressing change"}]}'::jsonb,
 '{"slots":{"s1":"t1","s2":"t3","s3":"t2","s4":"t4"}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem',
 'Prioritisation', 'Order of assessment after handover',
 'Hard', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_MCQ_531017', 'MCQ',
 'Four call bells sound at the same time on a surgical ward. Which call bell should the nurse answer FIRST?',
 'A call bell carries no information about acuity, so the nurse must sort the reported reasons by the same rules used for any priority decision. Sudden shortness of breath three hours after surgery is an unexpected symptom in a client within the vulnerable post-anaesthetic window and may indicate pulmonary embolism, atelectasis or fluid overload. A bedpan, a water jug and a television are comfort and convenience requests that can be met by another team member or shortly afterwards.',
 '{"options":[{"id":"A","text":"A client who wants the television turned down"},{"id":"B","text":"A client who would like a bedpan"},{"id":"C","text":"A client who cannot reach the water jug"},{"id":"D","text":"A client three hours after surgery who reports sudden shortness of breath"}]}'::jsonb,
 '{"answer":"D","feedback":{"A":"Incorrect. Adjusting a television is a convenience request and ranks last.","B":"Incorrect. Toileting is important for dignity but can be met by a colleague or immediately afterwards.","C":"Incorrect. A drink is a comfort need with no time pressure.","D":"Correct. Sudden breathlessness within 12 hours of surgery is an unexpected symptom in an unstable client."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem',
 'Prioritisation', 'Answering call bells',
 'Very easy', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_MCQ_531018', 'MCQ',
 'A practice nurse returns to a community clinic and finds four telephone messages waiting. Which message should the nurse return FIRST?',
 'Telephone triage uses the same rules as bedside triage, but the nurse must infer acuity from the words used. Black tarry stools in a client taking warfarin describe melaena, that is upper gastrointestinal bleeding in an anticoagulated client, which is haemorrhage and therefore always unstable. Rescheduling an appointment, advice about a decongestant for a head cold and a repeat prescription for an emollient are all routine and can be dealt with later in the session.',
 '{"options":[{"id":"A","text":"A client taking warfarin who reports black tarry stools since this morning"},{"id":"B","text":"A client who wishes to change the time of an appointment"},{"id":"C","text":"A client asking whether to take a decongestant for a head cold"},{"id":"D","text":"A client requesting a repeat prescription for an emollient"}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. Black tarry stools on warfarin indicate gastrointestinal haemorrhage, which is always unstable.","B":"Incorrect. Rescheduling an appointment is an administrative task.","C":"Incorrect. Advice about a self-limiting head cold is routine and can wait.","D":"Incorrect. A repeat prescription for an emollient carries no time pressure."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem',
 'Telephone triage', 'Prioritising messages',
 'Medium', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_MCQ_531019', 'MCQ',
 'A nurse reviews four newly written prescriptions before the medicine round. Which prescription should the nurse question BEFORE administering it?',
 'Questioning a prescription is a nursing responsibility, not a challenge to the prescriber. Concentrated potassium chloride must never be given as an intravenous bolus, because a sudden rise in serum potassium at the myocardium causes asystole; it must be diluted and infused at a controlled rate through a suitable line. The other three prescriptions use standard doses, routes and frequencies and can be given without clarification.',
 '{"options":[{"id":"A","text":"Enoxaparin 40 mg subcutaneously once daily"},{"id":"B","text":"Paracetamol 1 g orally every six hours"},{"id":"C","text":"Potassium chloride 20 mmol by intravenous bolus"},{"id":"D","text":"Ceftriaxone 1 g intravenously once daily"}]}'::jsonb,
 '{"answer":"C","feedback":{"A":"Incorrect. Enoxaparin 40 mg once daily is a standard prophylactic dose.","B":"Incorrect. Paracetamol 1 g six-hourly is a standard adult dose within the daily maximum.","C":"Correct. Potassium chloride given as a bolus causes fatal arrhythmia and must always be diluted and infused.","D":"Incorrect. Ceftriaxone 1 g once daily intravenously is a standard prescription."}}'::jsonb,
 'Physiological Integrity', 'Pharmacological and Parenteral Therapies',
 'Medical-Surgical', 'Multisystem',
 'Prescription review', 'Questioning an unsafe prescription',
 'Hard', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_SATA_531020', 'SATA',
 'A nurse reviews the prescriptions for several clients before the morning medicine round. Which prescriptions should the nurse clarify with the prescriber before administering? Select all that apply.',
 'A prescription is clarified when the drug is correct in principle but the client data make this dose or this timing unsafe. Digoxin is withheld and queried when the apical rate is below 60 beats per minute because of the risk of further bradycardia. A loop diuretic in the presence of a potassium of 2.6 mEq/L will worsen a dangerous hypokalaemia. Low molecular weight heparin with a platelet count of 22 000 per microlitre risks bleeding. Fluid for a client who is nil by mouth, analgesia for fever and a bronchodilator for wheeze are all appropriate.',
 '{"options":[{"id":"A","text":"Digoxin 125 micrograms orally for a client whose apical rate is 46 beats per minute"},{"id":"B","text":"Furosemide 40 mg orally for a client whose potassium is 2.6 mEq/L"},{"id":"C","text":"Paracetamol 1 g orally for a client with a temperature of 38.4 degrees Celsius"},{"id":"D","text":"Enoxaparin 40 mg subcutaneously for a client whose platelet count is 22 000 per microlitre"},{"id":"E","text":"Sodium chloride 0.9 per cent 1 litre intravenously over eight hours for a client who is nil by mouth"},{"id":"F","text":"Salbutamol by nebuliser for a client who is wheezing"}]}'::jsonb,
 '{"answers":["A","B","D"],"feedback":{"A":"Correct. Digoxin is withheld and queried when the apical rate is below 60 beats per minute.","B":"Correct. Furosemide will deepen an already dangerous hypokalaemia and risks arrhythmia.","C":"Incorrect. Paracetamol for fever at a standard dose needs no clarification.","D":"Correct. Anticoagulation with a platelet count of 22 000 per microlitre carries a serious bleeding risk.","E":"Incorrect. Maintenance fluid for a client who is nil by mouth is appropriate.","F":"Incorrect. A nebulised bronchodilator for wheeze is an appropriate prescription."}}'::jsonb,
 'Physiological Integrity', 'Pharmacological and Parenteral Therapies',
 'Medical-Surgical', 'Multisystem',
 'Prescription review', 'Clarifying before administration',
 'Hard', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728');

INSERT INTO nclex_bank_items (
  item_id, question_type, stem, rationale, content, correct,
  client_needs_category, client_needs_subcategory, nursing_subject, body_system,
  topic, subtopic, difficulty, difficulty_source, bloom_level, tags,
  marks, is_published, is_builder_visible, is_free_sample, cat_pool, batch_id
) VALUES
('NCLEX_MAT_531021', 'MATRIX',
 'A nurse is performing START triage at the scene of a multiple casualty incident. Assign the correct tag to each adult casualty.',
 'START triage sorts by ability to walk, then respiration, then perfusion, then mental status. Anyone who walks to the collection area is tagged green. A respiratory rate above 30 breaths per minute, an absent radial pulse or an inability to obey commands each gives a red or immediate tag. A casualty who breathes, perfuses and obeys commands but cannot walk is yellow or delayed. A casualty who does not breathe once the airway has been opened is tagged black, or expectant, because resources spent there cost the lives of salvageable casualties.',
 '{"rows":[{"id":"r1","text":"An adult who is walking around the scene with a forearm laceration"},{"id":"r2","text":"An adult with a respiratory rate of 36 breaths per minute after the airway is opened"},{"id":"r3","text":"An adult who remains apnoeic after the airway is repositioned"},{"id":"r4","text":"An adult with an open femoral fracture who cannot walk, has a respiratory rate of 18 breaths per minute, a palpable radial pulse and obeys commands"},{"id":"r5","text":"An adult who is breathing, has no palpable radial pulse and does not obey commands"}],"columns":[{"id":"c1","text":"Red — immediate"},{"id":"c2","text":"Yellow — delayed"},{"id":"c3","text":"Green — minor"},{"id":"c4","text":"Black — expectant"}],"row_label":"Casualty"}'::jsonb,
 '{"cells":{"r1":"c3","r2":"c1","r3":"c4","r4":"c2","r5":"c1"},"feedback":{}}'::jsonb,
 'Safe and Effective Care Environment', 'Safety and Infection Control',
 'Leadership and Management', 'Multisystem',
 'Disaster triage', 'START tag categories',
 'Hard', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_MCQ_531022', 'MCQ',
 'A nurse is triaging at the scene of a building collapse with 60 casualties and four responders. An adult is found unresponsive and apnoeic. After the airway is opened the casualty does not begin to breathe. Which action is correct?',
 'This is the deliberate reversal of everyday priority. On a ward the pulseless, breathless client is the very first priority and receives immediate resuscitation. In a mass casualty incident, where casualties far outnumber responders, the goal changes from doing everything possible for one client to doing the most good for the greatest number. Resuscitating one casualty with a very low chance of survival occupies responders who could stabilise several salvageable casualties, so the casualty is tagged expectant and the responder moves on.',
 '{"options":[{"id":"A","text":"Insert an oral airway and give rescue breaths for two minutes before deciding"},{"id":"B","text":"Begin cardiopulmonary resuscitation and continue until further help arrives"},{"id":"C","text":"Tag the casualty red and carry the casualty to the treatment area"},{"id":"D","text":"Tag the casualty as expectant, or black, and move on to the next casualty"}]}'::jsonb,
 '{"answer":"D","feedback":{"A":"Incorrect. Prolonged individual intervention is precisely what mass casualty triage is designed to avoid.","B":"Incorrect. Resuscitating one casualty in a mass casualty incident removes a responder from many who could survive.","C":"Incorrect. Red is for salvageable casualties with life-threatening but treatable problems.","D":"Correct. In a mass casualty incident a casualty who does not breathe once the airway is opened is tagged expectant so that resources reach salvageable casualties."}}'::jsonb,
 'Safe and Effective Care Environment', 'Safety and Infection Control',
 'Leadership and Management', 'Multisystem',
 'Disaster triage', 'Reversal of ordinary priority',
 'Very hard', 'CURATOR_LABEL', 'Evaluate', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_SATA_531023', 'SATA',
 'During START triage of adult casualties, which findings result in an immediate, or red, tag? Select all that apply.',
 'After the walking wounded have been directed away, START assesses three things in sequence: respiration, perfusion and mental status. A respiratory rate above 30 breaths per minute, an absent radial pulse or capillary refill longer than two seconds, and an inability to follow simple commands each produce a red tag on its own. A casualty who is walking is green whatever the injury looks like, a casualty who passes all three checks is yellow, and a casualty who stays apnoeic after the airway is opened is black.',
 '{"options":[{"id":"A","text":"A respiratory rate above 30 breaths per minute"},{"id":"B","text":"Absence of a palpable radial pulse"},{"id":"C","text":"Inability to follow simple commands"},{"id":"D","text":"An open forearm fracture in a casualty who is walking"},{"id":"E","text":"A respiratory rate of 18 breaths per minute with a palpable radial pulse in a casualty who obeys commands"},{"id":"F","text":"Apnoea that persists after the airway has been opened"}]}'::jsonb,
 '{"answers":["A","B","C"],"feedback":{"A":"Correct. A respiratory rate above 30 breaths per minute gives an immediate tag.","B":"Correct. An absent radial pulse indicates inadequate perfusion and gives an immediate tag.","C":"Correct. Failure to obey simple commands gives an immediate tag.","D":"Incorrect. A casualty who is walking is tagged green regardless of how the injury appears.","E":"Incorrect. Normal respiration, perfusion and mental status in a casualty who cannot walk gives a yellow, delayed tag.","F":"Incorrect. Persistent apnoea after the airway is opened gives a black, expectant tag."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem',
 'Disaster triage', 'Red tag criteria',
 'Easy', 'CURATOR_LABEL', 'Remember', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_SATA_531024', 'SATA',
 'Which statements describe how triage in a mass casualty incident differs from priority setting on a hospital ward? Select all that apply.',
 'Everyday priority setting assumes that resources are sufficient for every client, so the sickest client is treated first. Mass casualty triage assumes the opposite, and the ethical frame changes with it: the aim becomes the greatest good for the greatest number. That single change produces the two findings candidates most often get wrong, namely that the pulseless and breathless casualty is tagged last rather than first, and that ambulant casualties are directed away and reassessed later. Triage is also repeated, because casualty condition changes.',
 '{"options":[{"id":"A","text":"The aim shifts from doing the most for each individual to doing the most good for the greatest number"},{"id":"B","text":"A casualty who remains apnoeic after the airway is opened is tagged last rather than treated first"},{"id":"C","text":"Casualties who can walk are directed to a collection area and assessed later"},{"id":"D","text":"Every casualty receives a full set of observations before a tag is assigned"},{"id":"E","text":"Resources are directed first to the most severely injured casualty regardless of the chance of survival"},{"id":"F","text":"Triage decisions are made once at the scene and are not revisited"}]}'::jsonb,
 '{"answers":["A","B","C"],"feedback":{"A":"Correct. Scarcity of resources changes the ethical goal to the greatest good for the greatest number.","B":"Correct. This is the deliberate reversal of in-hospital priority.","C":"Correct. The walking wounded are tagged green and moved away so responders can reach the immediate casualties.","D":"Incorrect. START uses a rapid check of respiration, perfusion and mental status, not a full set of observations.","E":"Incorrect. That is everyday priority setting; in a mass casualty incident survivability guides the allocation.","F":"Incorrect. Casualties are re-triaged because condition changes over time."}}'::jsonb,
 'Safe and Effective Care Environment', 'Safety and Infection Control',
 'Leadership and Management', 'Multisystem',
 'Disaster triage', 'Contrast with ward priority',
 'Hard', 'CURATOR_LABEL', 'Understand', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_SATA_531025', 'SATA',
 'Which casualties at the scene of a multiple casualty incident would be tagged green, or minor? Select all that apply.',
 'The first step of START is to ask everyone who can walk to move to a designated collection area. Anyone who walks there is tagged green, because the ability to walk demonstrates an adequate airway, adequate perfusion and enough neurological function to follow an instruction. The visible injury does not change the tag. Casualties who cannot walk are then assessed individually, and a very high respiratory rate or an absent radial pulse gives an immediate tag.',
 '{"options":[{"id":"A","text":"An adult who walked to the collection point with a grazed knee"},{"id":"B","text":"An adult with a closed forearm fracture who is walking and talking"},{"id":"C","text":"An adult with a respiratory rate of 36 breaths per minute"},{"id":"D","text":"An adult with a superficial scalp laceration who is walking and following commands"},{"id":"E","text":"An adult who is unresponsive with no palpable radial pulse"}]}'::jsonb,
 '{"answers":["A","B","D"],"feedback":{"A":"Correct. Walking to the collection point gives a green tag.","B":"Correct. A closed fracture in a casualty who is walking and talking is a minor, green casualty.","C":"Incorrect. A respiratory rate above 30 breaths per minute gives a red, immediate tag.","D":"Correct. Walking and obeying commands with a superficial wound is a green casualty.","E":"Incorrect. An unresponsive casualty with no radial pulse is red, or black if apnoea persists after the airway is opened."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem',
 'Disaster triage', 'Green tag and the walking wounded',
 'Very easy', 'CURATOR_LABEL', 'Understand', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_MCQ_531026', 'MCQ',
 'A nurse is caring for a client two days after abdominal surgery. Over the last hour the respiratory rate has risen from 18 to 28 breaths per minute, the systolic blood pressure has fallen from 118 to 96 mmHg, and the client has become restless. Which action should the nurse take FIRST?',
 'Deterioration announces itself as a cluster of small changes in the hours before a cardiac arrest, most reliably a rising respiratory rate, a falling blood pressure and a change in behaviour or alertness. A rapid response team exists precisely to bring critical care assessment to the bedside during that window, before arrest occurs. Waiting, treating the restlessness with analgesia or deferring to the next round all use up the interval in which the outcome can still be changed.',
 '{"options":[{"id":"A","text":"Call the rapid response team"},{"id":"B","text":"Reassess the observations in thirty minutes"},{"id":"C","text":"Give the prescribed as-required analgesia and reassess"},{"id":"D","text":"Report the changes at the next scheduled medical round"}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. A rising respiratory rate with a falling blood pressure and new restlessness is early deterioration and warrants rapid response activation.","B":"Incorrect. A further thirty minutes of observation wastes the window in which deterioration is reversible.","C":"Incorrect. Restlessness here is more likely to be hypoxia or hypoperfusion than pain, and sedating analgesia may mask it.","D":"Incorrect. Deterioration is escalated when it is recognised, not at a scheduled time."}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential',
 'Medical-Surgical', 'Multisystem',
 'Deterioration and escalation', 'Rapid response activation',
 'Medium', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_SATA_531027', 'SATA',
 'Which findings should prompt the nurse to escalate to the medical team immediately rather than continue routine monitoring? Select all that apply.',
 'Escalation triggers are built around the physiological variables that predict arrest: respiratory rate at either extreme, a fall in the level of consciousness, and failing renal perfusion. A respiratory rate of 8 breaths per minute suggests respiratory depression, a new reduction in consciousness suggests a cerebral or metabolic cause, and a urine output below 0.5 mL per kilogram per hour sustained for four hours indicates inadequate organ perfusion. Values that sit at or near the usual baseline for the client are not escalation triggers.',
 '{"options":[{"id":"A","text":"A respiratory rate of 8 breaths per minute"},{"id":"B","text":"A new fall in the level of consciousness"},{"id":"C","text":"A urine output below 0.5 mL per kilogram per hour for four hours"},{"id":"D","text":"A blood pressure of 128/78 mmHg in a client whose usual reading is 130/80 mmHg"},{"id":"E","text":"A temperature of 37.2 degrees Celsius"},{"id":"F","text":"A heart rate of 76 beats per minute at rest"}]}'::jsonb,
 '{"answers":["A","B","C"],"feedback":{"A":"Correct. A respiratory rate of 8 breaths per minute indicates respiratory depression and requires immediate escalation.","B":"Correct. A new reduction in consciousness is one of the strongest predictors of deterioration.","C":"Correct. Sustained oliguria indicates inadequate organ perfusion.","D":"Incorrect. This reading is essentially the usual baseline for the client.","E":"Incorrect. A temperature of 37.2 degrees Celsius is within the normal range.","F":"Incorrect. A resting heart rate of 76 beats per minute is normal."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem',
 'Deterioration and escalation', 'Escalation triggers',
 'Medium', 'CURATOR_LABEL', 'Understand', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_MCQ_531028', 'MCQ',
 'Which client requires the nurse to summon the resuscitation team rather than the rapid response team?',
 'The two teams answer different questions. The rapid response team is called for a client who is deteriorating but still has a pulse and a respiratory effort, and its purpose is to prevent an arrest. The resuscitation team is called when the arrest has already happened, that is when the client is unresponsive with no signs of life. Choosing the rapid response team for an arrested client delays compressions and defibrillation; calling the resuscitation team for a deteriorating client wastes an opportunity for earlier, less invasive intervention.',
 '{"options":[{"id":"A","text":"A client whose systolic blood pressure has fallen to 88 mmHg and who is drowsy but rousable"},{"id":"B","text":"A client whose respiratory rate has risen to 30 breaths per minute and who is agitated"},{"id":"C","text":"A client who is unresponsive, apnoeic and pulseless"},{"id":"D","text":"A client whose urine output has fallen to 15 mL per hour over three hours"}]}'::jsonb,
 '{"answer":"C","feedback":{"A":"Incorrect. Hypotension with rousable drowsiness is deterioration, not arrest.","B":"Incorrect. This client is deteriorating with a pulse and respiratory effort, so the rapid response team is appropriate.","C":"Correct. An unresponsive, apnoeic and pulseless client has arrested and needs the resuscitation team.","D":"Incorrect. Falling urine output is an escalation trigger for the rapid response or medical team."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem',
 'Deterioration and escalation', 'Choosing the correct team',
 'Easy', 'CURATOR_LABEL', 'Understand', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_SATA_531029', 'SATA',
 'A nurse has several outstanding tasks near the end of a busy shift. Using the Maslow hierarchy as an ordering framework, which tasks address physiological needs and therefore take precedence? Select all that apply.',
 'Maslow orders competing needs when several are legitimate at the same time. Physiological needs, meaning oxygenation, circulation, nutrition, elimination, temperature and freedom from pain, are met before safety needs, and safety needs before love, esteem and self-actualisation. Communication with relatives and spiritual support are real needs, but they sit above the physiological level, and an administrative task such as a stock order is not a client need at all.',
 '{"options":[{"id":"A","text":"Giving the prescribed analgesia to a client reporting pain of 8 out of 10"},{"id":"B","text":"Assisting a client who is breathless to sit upright"},{"id":"C","text":"Telephoning a relative who asked for an update"},{"id":"D","text":"Suctioning a client who has noisy, gurgling respirations"},{"id":"E","text":"Arranging a chaplain visit for a client who is anxious"},{"id":"F","text":"Completing the ward stock order"}]}'::jsonb,
 '{"answers":["A","B","D"],"feedback":{"A":"Correct. Relief of severe pain is a physiological need.","B":"Correct. Positioning to improve ventilation addresses oxygenation, a physiological need.","C":"Incorrect. Communication with relatives is important but sits above the physiological level.","D":"Correct. Clearing the airway is the most basic physiological need of all.","E":"Incorrect. Spiritual support addresses a higher-level need.","F":"Incorrect. A stock order is an administrative task, not a client need."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem',
 'Ordering frameworks', 'Maslow hierarchy',
 'Easy', 'CURATOR_LABEL', 'Understand', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_MCQ_531030', 'MCQ',
 'A nurse enters a four-bedded bay where four clients need attention at the same moment. Which client should the nurse attend to FIRST?',
 'The airway, breathing and circulation framework outranks every other ordering rule when the clients differ on those variables, because an obstructed airway kills faster than any other problem in the room. Gurgling respirations with secretions at the mouth describe a partially obstructed airway that will become complete if nothing is done. An alarming pump, nausea and an uncomfortable bed height are all real but none of them threatens ventilation or perfusion.',
 '{"options":[{"id":"A","text":"A client whose bed needs to be lowered"},{"id":"B","text":"A client whose intravenous infusion pump is alarming"},{"id":"C","text":"A client who reports feeling nauseated"},{"id":"D","text":"A client with gurgling respirations and secretions pooling at the mouth"}]}'::jsonb,
 '{"answer":"D","feedback":{"A":"Incorrect. Bed height is a comfort and safety task with no immediate threat.","B":"Incorrect. An alarming pump interrupts therapy but does not threaten the airway.","C":"Incorrect. Nausea is uncomfortable and should be treated, but after the airway is secured.","D":"Correct. Gurgling respirations indicate a threatened airway, which outranks everything else."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem',
 'Ordering frameworks', 'Airway breathing circulation',
 'Very easy', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728');

INSERT INTO nclex_bank_items (
  item_id, question_type, stem, rationale, content, correct,
  client_needs_category, client_needs_subcategory, nursing_subject, body_system,
  topic, subtopic, difficulty, difficulty_source, bloom_level, tags,
  marks, is_published, is_builder_visible, is_free_sample, cat_pool, batch_id
) VALUES
('NCLEX_MCQ_531031', 'MCQ',
 'A nurse reviews four clients, all of whom have a patent airway, unlaboured breathing and a strong regular pulse. Which client should the nurse assess FIRST?',
 'The airway, breathing and circulation framework only sorts clients when they differ on those three variables. Here every client passes all three, so the framework yields no answer and the nurse moves down the rule stack: acute and changing beats chronic and unchanged, and the organ hierarchy breaks the remaining tie with the brain at the top. New confusion and drowsiness over 15 minutes is an acute neurological change that may reflect hypoxia, hypoglycaemia, sepsis or a stroke, none of which will have altered the pulse yet.',
 '{"options":[{"id":"A","text":"A client who has become confused and drowsy over the last 15 minutes"},{"id":"B","text":"A client who reports feeling anxious about surgery scheduled for tomorrow"},{"id":"C","text":"A client whose pressure injury dressing is due to be changed"},{"id":"D","text":"A client with long-standing constipation who has not opened the bowels for two days"}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. When all clients are equal on airway, breathing and circulation, the acute neurological change wins because the brain ranks highest in the organ hierarchy.","B":"Incorrect. Anticipatory anxiety is a psychosocial need and sits below an acute physiological change.","C":"Incorrect. A scheduled dressing change is a routine task on a chronic problem.","D":"Incorrect. Long-standing constipation is a chronic, unchanged finding."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem',
 'Ordering frameworks', 'When ABC does not discriminate',
 'Very hard', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_MCQ_531032', 'MCQ',
 'A client with heart failure becomes breathless after the morning wash. The nurse notes that the oxygen saturation has fallen to 89 per cent on room air. Which action should the nurse take FIRST?',
 'The nursing process orders actions when no immediate life threat forces the hand: assessment precedes diagnosis, planning, implementation and evaluation. A single saturation reading is one data point and does not by itself identify the cause, which could be pulmonary oedema, exertion, a mucus plug, atelectasis or a faulty probe. Completing the assessment establishes what is actually happening and gives the medical team the information it needs, whereas acting on one number risks the wrong intervention.',
 '{"options":[{"id":"A","text":"Administer the prescribed as-required furosemide"},{"id":"B","text":"Assess the respiratory rate, effort and breath sounds and repeat the oxygen saturation"},{"id":"C","text":"Contact the medical team to request a chest radiograph"},{"id":"D","text":"Document the finding in the care record"}]}'::jsonb,
 '{"answer":"B","feedback":{"A":"Incorrect. A diuretic is an intervention chosen after assessment identifies fluid overload as the cause.","B":"Correct. The nursing process places assessment before intervention when there is no immediate life threat.","C":"Incorrect. Escalation is appropriate, but the medical team needs assessment data to act on.","D":"Incorrect. Documentation follows assessment and action, it does not replace them."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem',
 'Ordering frameworks', 'Nursing process ordering',
 'Easy', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_MCQ_531033', 'MCQ',
 'A nurse is sitting with a client who has just been told of a terminal diagnosis and is crying. A healthcare assistant reports that another client, four hours after total hip replacement, has become breathless and is reporting chest pain. Which action should the nurse take FIRST?',
 'Two clients need the nurse at once, and only one situation is time-critical. Breathlessness with chest pain in a client four hours after joint replacement suggests pulmonary embolism, a physiological emergency in a fresh post-operative client. Psychosocial need is real but does not outrank it. The nurse does not abandon the distressed client, however: presence can be transferred to a colleague, which is why explaining, arranging cover and then going is the complete answer rather than simply leaving.',
 '{"options":[{"id":"A","text":"Explain that an urgent problem needs attention, ask a colleague to stay with the client, and go to the second client"},{"id":"B","text":"Stay with the first client until the distress settles and then review the second client"},{"id":"C","text":"Ask the healthcare assistant to sit the second client upright and start oxygen"},{"id":"D","text":"Ask the healthcare assistant to record a full set of observations and report back"}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. The physiological emergency takes precedence, and transferring presence to a colleague meets the psychosocial need without delay.","B":"Incorrect. Delaying assessment of a possible pulmonary embolism risks the life of the second client.","C":"Incorrect. Starting oxygen is a prescribed intervention and assessment is not within the assistant scope.","D":"Incorrect. Delegating observation does not substitute for assessment by the nurse in a possible embolism."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem',
 'Time management', 'Two clients at once',
 'Hard', 'CURATOR_LABEL', 'Evaluate', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_SATA_531034', 'SATA',
 'Which actions should the nurse take during the first thirty minutes of a shift on a busy ward? Select all that apply.',
 'The opening half hour sets the shape of the shift. Three things belong in it: laying eyes on the least stable client so that the handover picture is verified rather than assumed, identifying anything that is time-critical within the hour such as an antibiotic due or a result to act on, and deciding what will be assigned to other team members. Documentation, restocking and personally performing every observation are either time-flexible or a poor use of registered nurse time.',
 '{"options":[{"id":"A","text":"Lay eyes on the client identified at handover as the least stable"},{"id":"B","text":"Identify prescriptions and results that must be acted on within the hour"},{"id":"C","text":"Complete all of the routine documentation for the shift"},{"id":"D","text":"Decide which tasks will be assigned to the licensed practical nurse and the healthcare assistant"},{"id":"E","text":"Restock the treatment room"},{"id":"F","text":"Personally record a full set of observations on every client"}]}'::jsonb,
 '{"answers":["A","B","D"],"feedback":{"A":"Correct. Verifying the least stable client early confirms or corrects the handover picture.","B":"Correct. Time-critical prescriptions and results must be identified before the shift fills up.","C":"Incorrect. Documentation cannot be completed for events that have not yet happened.","D":"Correct. Planning assignment early prevents the nurse becoming the bottleneck later.","E":"Incorrect. Restocking is a time-flexible task.","F":"Incorrect. Routine observations on stable clients may be assigned, freeing the nurse for assessment."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem',
 'Time management', 'Start of shift planning',
 'Easy', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_SATA_531035', 'SATA',
 'The workload on a shift has grown beyond the time available. Which actions by the nurse are appropriate? Select all that apply.',
 'When demand exceeds capacity the nurse changes the plan and tells someone, rather than quietly cutting corners. Reprioritising so that time-critical work is protected, reporting the shortfall to the charge nurse so that resources can be moved, and assigning work that falls within the scope of other team members are all legitimate. Omitting observations on the least stable client, documenting medicines before they are given and asking relatives to give care are unsafe and, in the case of charting in advance, falsification of the record.',
 '{"options":[{"id":"A","text":"Reprioritise the plan so that time-critical tasks are completed first"},{"id":"B","text":"Inform the charge nurse that the workload cannot be completed safely and request support"},{"id":"C","text":"Assign tasks that fall within the scope of the healthcare assistant"},{"id":"D","text":"Omit the four-hourly observations on the least stable client to save time"},{"id":"E","text":"Chart medicines as given and administer them when time allows"},{"id":"F","text":"Ask relatives to help with the medicine round"}]}'::jsonb,
 '{"answers":["A","B","C"],"feedback":{"A":"Correct. Reprioritising protects the work that cannot safely be delayed.","B":"Correct. Escalating an unsafe workload allows the charge nurse to redistribute resources.","C":"Correct. Assigning within scope is the intended use of the team.","D":"Incorrect. The least stable client is the last person whose monitoring should be reduced.","E":"Incorrect. Charting before administration falsifies the record and risks a duplicate dose.","F":"Incorrect. Medicine administration cannot be given to relatives."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem',
 'Time management', 'Workload exceeding capacity',
 'Medium', 'CURATOR_LABEL', 'Evaluate', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_SATA_531036', 'SATA',
 'Which tasks may the nurse delegate to an experienced healthcare assistant on a general ward? Select all that apply.',
 'Delegation to unlicensed personnel covers standard, predictable tasks on clients whose condition is stable, where the outcome does not depend on nursing judgement. Assisting with hygiene, recording a weight and taking and reporting routine observations all qualify. Teaching, assessment and any decision about whether a client is well enough to do something require the knowledge base and accountability of the registered nurse and cannot be delegated, however experienced the assistant is.',
 '{"options":[{"id":"A","text":"Assisting a stable client to shower"},{"id":"B","text":"Recording the daily weight of a client with heart failure"},{"id":"C","text":"Teaching a newly diagnosed client to self-administer insulin"},{"id":"D","text":"Taking routine observations on a stable client and reporting them to the nurse"},{"id":"E","text":"Assessing a wound that has begun to smell"},{"id":"F","text":"Deciding whether a client is well enough to walk to the bathroom"}]}'::jsonb,
 '{"answers":["A","B","D"],"feedback":{"A":"Correct. Assisting a stable client with hygiene is a standard delegable task.","B":"Correct. Measuring and recording a weight is a data-collection task; interpreting the trend remains with the nurse.","C":"Incorrect. Teaching requires the knowledge base of the registered nurse.","D":"Correct. Routine observations on a stable client may be delegated, with the reported values interpreted by the nurse.","E":"Incorrect. Wound assessment is a nursing assessment and cannot be delegated.","F":"Incorrect. Deciding whether a client is safe to mobilise is a nursing judgement."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem',
 'Delegation', 'Unlicensed assistive personnel',
 'Very easy', 'CURATOR_LABEL', 'Understand', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_MCQ_531037', 'MCQ',
 'A nurse finds that the tubing of a chest drainage system has become disconnected from the water seal for a client with a pneumothorax. Which action should the nurse take FIRST?',
 'FIRST asks about sequence, and the sequence is decided by what is happening at this instant. The open tube is a direct channel between the pleural space and the atmosphere, so with each inspiration air is drawn in and the pneumothorax enlarges. Clamping close to the chest wall closes that channel immediately using only the hands. It is a momentary measure and must not be left in place, because a clamped tube in a client with an air leak can produce a tension pneumothorax.',
 '{"options":[{"id":"A","text":"Clamp the chest tube close to the chest wall"},{"id":"B","text":"Notify the medical team and request a chest radiograph"},{"id":"C","text":"Apply a new occlusive dressing over the insertion site"},{"id":"D","text":"Reconnect the contaminated tubing to the drainage system"}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. Clamping close to the chest wall immediately stops atmospheric air entering the pleural space.","B":"Incorrect. Notification is necessary but does not stop air entering the chest in the meantime.","C":"Incorrect. The insertion site is not the breach; the open tubing is.","D":"Incorrect. Reconnecting contaminated tubing introduces infection into the pleural space."}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential',
 'Medical-Surgical', 'Multisystem',
 'Chest drainage', 'First action after disconnection',
 'Medium', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_MCQ_531038', 'MCQ',
 'The tubing of a chest drainage system has become disconnected from the water seal for a client with a pneumothorax. Which action by the nurse is BEST?',
 'BEST asks which action solves the problem rather than which comes first in time. Clamping buys seconds but converts an open pneumothorax into a closed one, so if air is still leaking from the lung the pressure has nowhere to go and a tension pneumothorax can develop. Submerging the open end about two centimetres below sterile water re-creates a one-way valve: air can leave the pleural space on expiration but cannot re-enter on inspiration. That is why clamping is the first action and submerging is the best one.',
 '{"options":[{"id":"A","text":"Clamp the chest tube and leave it clamped until the medical team arrives"},{"id":"B","text":"Submerge the open end of the tube about two centimetres below the surface of sterile water"},{"id":"C","text":"Reconnect the contaminated tubing to the drainage system"},{"id":"D","text":"Milk the chest tube to clear any clot before reconnecting"}]}'::jsonb,
 '{"answer":"B","feedback":{"A":"Incorrect. Prolonged clamping in the presence of an air leak risks a tension pneumothorax.","B":"Correct. Submerging the tube end restores a water seal, allowing air out while preventing air entering.","C":"Incorrect. Contaminated tubing must not be reconnected because of the infection risk.","D":"Incorrect. Milking or stripping generates high negative pressure and damages lung tissue."}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential',
 'Medical-Surgical', 'Multisystem',
 'Chest drainage', 'Best action after disconnection',
 'Hard', 'CURATOR_LABEL', 'Evaluate', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_MCQ_531039', 'MCQ',
 'A nurse finds that the abdominal wound dressing of a client four hours after surgery is soaked with bright red blood and that fresh blood is running onto the sheet. Which action should the nurse take FIRST?',
 'FIRST asks what must happen in the next few seconds. Firm direct pressure over the wound is the only action that reduces blood loss immediately, requires no equipment and no prescription, and can be started with the hands already at the bedside. Observations, fluids and escalation all follow within moments, but each of them takes time during which uncontrolled loss continues.',
 '{"options":[{"id":"A","text":"Contact the surgical team"},{"id":"B","text":"Record a full set of observations"},{"id":"C","text":"Increase the rate of the intravenous infusion"},{"id":"D","text":"Apply firm direct pressure over the dressing"}]}'::jsonb,
 '{"answer":"D","feedback":{"A":"Incorrect. The surgical team must be contacted, but not before pressure is applied.","B":"Incorrect. Observations quantify the effect of the loss but do not slow it.","C":"Incorrect. Fluid replacement is important but comes after the bleeding is controlled and usually requires a prescription change.","D":"Correct. Direct pressure is the only measure that reduces the loss immediately and needs nothing but the hands."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Medical-Surgical', 'Multisystem',
 'Post-operative haemorrhage', 'First action',
 'Medium', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_MCQ_531040', 'MCQ',
 'A client four hours after abdominal surgery has bled heavily through the wound dressing. Direct pressure has been applied and the surgical team has been contacted. Which nursing action is the PRIORITY over the next hour?',
 'PRIORITY asks what matters most rather than what happens first. Once the bleeding point is under pressure, the threat to life is no longer the blood on the sheet but the falling circulating volume behind it. Maintaining perfusion, guided by frequent observations of pulse, blood pressure, capillary refill, urine output and conscious level, is what keeps the brain, heart and kidneys supplied until the surgical team can secure haemostasis. Dressing changes, positioning and oral fluids do not address volume loss.',
 '{"options":[{"id":"A","text":"Reinforcing the dressing every hour and recording the number of pads used"},{"id":"B","text":"Maintaining circulating volume and tissue perfusion, guided by frequent observations, until the surgical team reviews the client"},{"id":"C","text":"Repositioning the client hourly to prevent pressure damage"},{"id":"D","text":"Encouraging oral fluids to replace the volume that has been lost"}]}'::jsonb,
 '{"answer":"B","feedback":{"A":"Incorrect. Reinforcement and estimation of loss are useful monitoring, but they do not address the threat to perfusion.","B":"Correct. Once bleeding is controlled at the surface, maintaining perfusion is what protects the vital organs.","C":"Incorrect. Pressure area care is important but not the priority during active volume loss.","D":"Incorrect. Oral fluids are too slow and the client may need to return to theatre and remain nil by mouth."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Medical-Surgical', 'Multisystem',
 'Post-operative haemorrhage', 'Priority of ongoing care',
 'Hard', 'CURATOR_LABEL', 'Evaluate', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728');

INSERT INTO nclex_bank_items (
  item_id, question_type, stem, rationale, content, correct,
  client_needs_category, client_needs_subcategory, nursing_subject, body_system,
  topic, subtopic, difficulty, difficulty_source, bloom_level, tags,
  marks, is_published, is_builder_visible, is_free_sample, cat_pool, batch_id
) VALUES
('NCLEX_MCQ_531041', 'MCQ',
 'A healthcare assistant reports that a client has been found sitting on the floor beside the bed. Which action should the nurse take FIRST?',
 'After an unwitnessed fall the nurse does not know whether the client fell because of injury, syncope, hypoglycaemia, arrhythmia or simple imbalance, and does not know what damage the fall itself caused. Assessment therefore comes before movement, because lifting a client with a fractured neck of femur or an unstable spinal injury converts a manageable injury into a serious one. Documentation and family contact follow once the client has been assessed and made safe.',
 '{"options":[{"id":"A","text":"Assess the client for injury and check the level of consciousness and observations"},{"id":"B","text":"Help the client back into bed"},{"id":"C","text":"Complete an incident report"},{"id":"D","text":"Telephone the family to inform them of the fall"}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. Assessment precedes movement because moving an injured client can worsen the injury.","B":"Incorrect. Lifting before assessment risks converting an occult fracture into a displaced one.","C":"Incorrect. The incident report is completed after the client has been assessed and made safe.","D":"Incorrect. The family must be informed, but only after the condition of the client is known."}}'::jsonb,
 'Safe and Effective Care Environment', 'Safety and Infection Control',
 'Leadership and Management', 'Multisystem',
 'Falls', 'Immediate response to a fall',
 'Easy', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_MCQ_531042', 'MCQ',
 'A client has had an unwitnessed fall while walking to the bathroom at night. No injury was sustained. Which action by the nurse BEST reduces the risk of a further fall during this admission?',
 'BEST asks which action changes the underlying risk rather than which action feels protective. A repeated falls assessment identifies the specific causes for this client, such as nocturia, orthostatic hypotension, sedating medicines, poor lighting or unsuitable footwear, and an individualised plan including scheduled toileting removes the reason the client was walking unaccompanied. Bed rails and lap tables are restraints that increase injury through climbing and entrapment, and instructing a client not to get up does not address why the client got up.',
 '{"options":[{"id":"A","text":"Raise all four bed rails at night"},{"id":"B","text":"Repeat the falls risk assessment and build the identified risks into an individualised plan that includes scheduled toileting and the call bell within reach"},{"id":"C","text":"Instruct the client not to get out of bed without assistance"},{"id":"D","text":"Seat the client in a chair with a table placed across the front"}]}'::jsonb,
 '{"answer":"B","feedback":{"A":"Incorrect. Four raised rails act as a restraint and increase injury from climbing and entrapment.","B":"Correct. Identifying and removing the specific causes, including the need to toilet, is what reduces further falls.","C":"Incorrect. Instruction alone does not address the need that prompted the client to get up.","D":"Incorrect. A table across a chair is a restraint and is not a fall prevention measure."}}'::jsonb,
 'Safe and Effective Care Environment', 'Safety and Infection Control',
 'Leadership and Management', 'Multisystem',
 'Falls', 'Preventing recurrence',
 'Hard', 'CURATOR_LABEL', 'Evaluate', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_SELN_531043', 'SELECT_N',
 'A nurse reviews six clients at the start of a shift. Which 3 clients should the nurse regard as unstable?',
 'A client is unstable when the situation is acute, newly admitted, changing, unexpected for the diagnosis, or within 12 hours of general anaesthesia, and always when haemorrhage, a temperature above 40.5 degrees Celsius, hypoglycaemia or absent pulse or breathing is present. Applying that list mechanically prevents the common error of ranking by how serious the diagnosis sounds. Recovery on day three, a stable chronic oxygen saturation and controlled expected pain are all stable markers.',
 '{"options":[{"id":"A","text":"A client admitted 40 minutes ago with new-onset atrial fibrillation and a heart rate of 148 beats per minute"},{"id":"B","text":"A client three days after cholecystectomy who is tolerating a light diet"},{"id":"C","text":"A client whose capillary blood glucose is 2.5 mmol/L"},{"id":"D","text":"A client with emphysema whose oxygen saturation has been 91 per cent for the past two days"},{"id":"E","text":"A client two hours after general anaesthesia whose systolic blood pressure has fallen from 118 to 84 mmHg"},{"id":"F","text":"A client with terminal cancer whose pain is controlled on the prescribed regimen"}],"select_count":3}'::jsonb,
 '{"answers":["A","C","E"],"feedback":{"A":"Correct. Newly admitted, acute and with a changing rhythm — three unstable markers together.","B":"Incorrect. Post-operative day three tolerating diet is stable.","C":"Correct. Hypoglycaemia is always unstable.","D":"Incorrect. A saturation of 91 per cent unchanged for two days is the expected baseline in emphysema.","E":"Correct. General anaesthesia within 12 hours with a falling blood pressure is a changing, unstable picture.","F":"Incorrect. Controlled pain that is expected with the diagnosis is a stable marker."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem',
 'Prioritisation', 'Identifying unstable clients',
 'Medium', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_SELN_531044', 'SELECT_N',
 'A nurse assesses a client eight hours after bowel resection. Which 3 findings require immediate escalation to the surgical team?',
 'Post-operative escalation triggers are the findings that indicate bleeding, perforation or failing perfusion rather than ordinary recovery. Oliguria below roughly 0.5 mL per kilogram per hour, a rigid abdomen with new severe pain and a rising heart rate with cool peripheries together describe hypovolaemia and possible intra-abdominal catastrophe. A dry intact dressing, absent bowel sounds at eight hours and a dry mouth while nil by mouth are all expected at this stage.',
 '{"options":[{"id":"A","text":"A urine output of 10 mL per hour for the last three hours"},{"id":"B","text":"An abdominal dressing that is dry and intact"},{"id":"C","text":"A rigid, board-like abdomen with new severe pain"},{"id":"D","text":"Absent bowel sounds"},{"id":"E","text":"A heart rate that has risen from 82 to 126 beats per minute with cool peripheries"},{"id":"F","text":"A report of a dry mouth while the client is nil by mouth"}],"select_count":3}'::jsonb,
 '{"answers":["A","C","E"],"feedback":{"A":"Correct. Sustained oliguria indicates inadequate renal perfusion and must be escalated.","B":"Incorrect. A dry intact dressing is a reassuring finding.","C":"Correct. A rigid abdomen with new severe pain suggests perforation or peritonitis.","D":"Incorrect. Bowel sounds are routinely absent for the first day or two after bowel surgery.","E":"Correct. Tachycardia with cool peripheries is compensated hypovolaemia and must be escalated.","F":"Incorrect. A dry mouth is expected while nil by mouth and is managed with mouth care."}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential',
 'Medical-Surgical', 'Multisystem',
 'Post-operative assessment', 'Findings requiring escalation',
 'Medium', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_SELN_531045', 'SELECT_N',
 'A charge nurse must free beds on a full medical ward. Which 3 clients are stable enough to be discharged home today?',
 'Discharge readiness is prioritisation in the opposite direction, and it uses the same markers. A client who is beyond the vulnerable post-operative window, apyrexial, tolerating oral intake, controlled on oral medicines and provided with follow-up carries no unstable marker. Weight gain in heart failure signals accumulating fluid, recent hypoglycaemia signals unresolved instability and drowsiness within four hours of general anaesthesia is inside the window in which airway and circulation can still change.',
 '{"options":[{"id":"A","text":"A client 26 hours after laparoscopic cholecystectomy who is apyrexial, tolerating diet and comfortable on oral analgesia"},{"id":"B","text":"A client with heart failure whose weight has risen 2.5 kg over two days"},{"id":"C","text":"A client treated for cellulitis whose redness has receded and who is changing to oral antibiotics"},{"id":"D","text":"A client whose capillary blood glucose was 2.8 mmol/L one hour ago"},{"id":"E","text":"A client with a urinary tract infection who has been apyrexial for 24 hours, is drinking freely and has follow-up arranged"},{"id":"F","text":"A client four hours after general anaesthesia who remains drowsy"}],"select_count":3}'::jsonb,
 '{"answers":["A","C","E"],"feedback":{"A":"Correct. Beyond 24 hours post-operatively, apyrexial, eating and comfortable on oral analgesia is a stable discharge picture.","B":"Incorrect. A 2.5 kg gain over two days indicates fluid retention and unresolved heart failure.","C":"Correct. Receding cellulitis with a change to oral antibiotics and follow-up arranged is a safe discharge.","D":"Incorrect. Hypoglycaemia within the last hour means the client is not yet stable.","E":"Correct. Apyrexial for 24 hours, drinking and with follow-up arranged meets discharge criteria.","F":"Incorrect. Drowsiness four hours after general anaesthesia is inside the unstable post-anaesthetic window."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem',
 'Prioritisation', 'Discharge readiness',
 'Very hard', 'CURATOR_LABEL', 'Evaluate', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_SELN_531046', 'SELECT_N',
 'A triage nurse reviews the emergency department waiting area. Which 3 clients should be moved to a treatment space immediately?',
 'Emergency triage inside the hospital follows ordinary priority rules, not mass casualty rules: the sickest client is seen first. Central chest pain with diaphoresis of 30 minutes duration falls inside the window in which reperfusion changes the outcome. A respiratory rate of 32 breaths per minute with single-word speech is impending respiratory failure. Drowsiness with a glucose of 2.2 mmol/L is hypoglycaemia, always unstable. A day-old sprain, a three-week cough with a near-normal temperature and a prescription request are all stable.',
 '{"options":[{"id":"A","text":"An adult with central chest pain that began 30 minutes ago who is diaphoretic"},{"id":"B","text":"An adult with an ankle sprain sustained yesterday"},{"id":"C","text":"An adult with a productive cough for three weeks and a temperature of 37.4 degrees Celsius"},{"id":"D","text":"An adult with a respiratory rate of 32 breaths per minute who can speak only in single words"},{"id":"E","text":"An adult who is drowsy and whose capillary blood glucose is 2.2 mmol/L"},{"id":"F","text":"An adult requesting a repeat prescription for antihypertensive medicines"}],"select_count":3}'::jsonb,
 '{"answers":["A","D","E"],"feedback":{"A":"Correct. Acute chest pain with diaphoresis may be a myocardial infarction and is time-critical.","B":"Incorrect. A sprain sustained yesterday is a chronic, stable injury in triage terms.","C":"Incorrect. A three-week cough with a near-normal temperature is not time-critical.","D":"Correct. Single-word speech with a respiratory rate of 32 breaths per minute indicates impending respiratory failure.","E":"Correct. Hypoglycaemia with reduced consciousness is always unstable.","F":"Incorrect. A prescription request is an administrative need."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem',
 'Emergency triage', 'In-hospital triage priorities',
 'Very hard', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_SELN_531047', 'SELECT_N',
 'A nurse completes a sepsis screen on a client who has a urinary catheter and a suspected urinary tract infection. Which 3 findings require the nurse to escalate to the medical team within one hour?',
 'The red flags in a sepsis screen are the signs that infection has begun to affect organ function rather than the signs of infection itself. A systolic blood pressure below 90 mmHg indicates failing perfusion, a respiratory rate of 25 breaths per minute or more reflects the metabolic acidosis of poor tissue oxygenation, and new confusion in a previously alert client shows cerebral involvement. Any of the three triggers the one-hour bundle of cultures, antibiotics, fluids, lactate, oxygen and urine measurement.',
 '{"options":[{"id":"A","text":"A systolic blood pressure of 86 mmHg"},{"id":"B","text":"A respiratory rate of 26 breaths per minute"},{"id":"C","text":"New confusion in a client who was previously alert"},{"id":"D","text":"A temperature of 37.6 degrees Celsius"},{"id":"E","text":"A heart rate of 92 beats per minute"},{"id":"F","text":"A urine output of 60 mL in the last hour"}],"select_count":3}'::jsonb,
 '{"answers":["A","B","C"],"feedback":{"A":"Correct. A systolic pressure below 90 mmHg is a sepsis red flag indicating failing perfusion.","B":"Correct. A respiratory rate of 25 breaths per minute or more is a sepsis red flag.","C":"Correct. New confusion indicates cerebral involvement and is a red flag.","D":"Incorrect. A temperature of 37.6 degrees Celsius is only marginally raised and is not a red flag on its own.","E":"Incorrect. A heart rate of 92 beats per minute is below the red flag threshold.","F":"Incorrect. Sixty millilitres in an hour is an adequate urine output for most adults."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Medical-Surgical', 'Multisystem',
 'Deterioration and escalation', 'Sepsis red flags',
 'Medium', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_MAT_531048', 'MATRIX',
 'A nurse reviews the findings recorded during an assessment round. Decide whether each finding requires immediate escalation or whether routine monitoring may continue.',
 'Escalation is triggered by change and by findings that are unexpected for the known diagnosis. A urine output that has fallen below roughly 0.5 mL per kilogram per hour, a systolic pressure that has dropped by nearly 40 mmHg in an hour and a new reduction in alertness all describe movement away from the baseline. A low-grade fever on treatment, a functioning long-standing colostomy and controlled incisional pain 30 hours after surgery all match what the diagnosis predicts, so monitoring continues.',
 '{"rows":[{"id":"r1","text":"A client six hours after abdominal surgery whose urine output has been 12 mL per hour for three hours"},{"id":"r2","text":"A client with pneumonia whose temperature is 37.9 degrees Celsius on day two of antibiotics"},{"id":"r3","text":"A client whose systolic blood pressure has fallen from 124 to 86 mmHg in one hour"},{"id":"r4","text":"A client with a long-standing colostomy who is passing formed stool"},{"id":"r5","text":"A client who has become drowsy and confused since the last set of observations"},{"id":"r6","text":"A client 30 hours after hip replacement reporting incisional pain relieved by the prescribed analgesia"}],"columns":[{"id":"c1","text":"Escalate immediately"},{"id":"c2","text":"Continue routine monitoring"}],"row_label":"Finding"}'::jsonb,
 '{"cells":{"r1":"c1","r2":"c2","r3":"c1","r4":"c2","r5":"c1","r6":"c2"},"feedback":{}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem',
 'Deterioration and escalation', 'Escalate or monitor',
 'Medium', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_MAT_531049', 'MATRIX',
 'A nurse receives a client into the recovery area after surgery under general anaesthesia. Classify each finding as expected or unexpected.',
 'Knowing what is expected after general anaesthesia is what allows the nurse to spot the client who is deviating. Shivering, nausea that responds to an antiemetic and drowsiness that lightens with stimulation are all normal consequences of anaesthetic agents and heat loss in theatre. A saturation of 88 per cent despite supplemental oxygen indicates inadequate ventilation or oxygenation, and brisk bright red drainage soaking a dressing within minutes is haemorrhage. Both are unexpected and both require immediate escalation.',
 '{"rows":[{"id":"r1","text":"Shivering 20 minutes after general anaesthesia"},{"id":"r2","text":"An oxygen saturation of 88 per cent on 4 litres per minute of oxygen"},{"id":"r3","text":"Nausea that is relieved by the prescribed antiemetic"},{"id":"r4","text":"Brisk bright red drainage soaking the dressing within 10 minutes"},{"id":"r5","text":"Drowsiness that lightens when the client is spoken to"}],"columns":[{"id":"c1","text":"Expected"},{"id":"c2","text":"Unexpected — escalate"}],"row_label":"Finding"}'::jsonb,
 '{"cells":{"r1":"c1","r2":"c2","r3":"c1","r4":"c2","r5":"c1"},"feedback":{}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential',
 'Medical-Surgical', 'Multisystem',
 'Post-anaesthetic recovery', 'Expected and unexpected findings',
 'Easy', 'CURATOR_LABEL', 'Understand', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_MMR_531050', 'MATRIX_MR',
 'A nurse receives five reports at once. For each client, select every action that is appropriate. More than one action may apply to a client.',
 'Two separate judgements are needed for each report: how quickly the nurse must attend, and whether the medical team must be told. Clients with an airway threat, hypoglycaemia or a chest drain that has stopped functioning need both, because the nurse must act now and the situation exceeds what nursing measures alone can resolve. Comfort requests and discharge conversations need neither and are safely folded into the routine round, which is what protects the time to respond to the others.',
 '{"rows":[{"id":"r1","text":"A client four hours after thyroidectomy reporting a tight feeling in the neck and a hoarse voice"},{"id":"r2","text":"A client asking for a second pillow"},{"id":"r3","text":"A client whose capillary blood glucose is 2.3 mmol/L and who is sweating"},{"id":"r4","text":"A client two days after appendicectomy who wants to discuss discharge arrangements"},{"id":"r5","text":"A client whose chest drain has stopped swinging and who has become breathless"}],"columns":[{"id":"c1","text":"See within five minutes"},{"id":"c2","text":"Notify the medical team"},{"id":"c3","text":"May wait until routine rounds"}],"row_label":"Client report"}'::jsonb,
 '{"cells":{"r1":["c1","c2"],"r2":["c3"],"r3":["c1","c2"],"r4":["c3"],"r5":["c1","c2"]},"feedback":{}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem',
 'Prioritisation', 'Speed of response and escalation',
 'Very hard', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728');

INSERT INTO nclex_bank_items (
  item_id, question_type, stem, rationale, content, correct,
  client_needs_category, client_needs_subcategory, nursing_subject, body_system,
  topic, subtopic, difficulty, difficulty_source, bloom_level, tags,
  marks, is_published, is_builder_visible, is_free_sample, cat_pool, batch_id
) VALUES
('NCLEX_MMR_531051', 'MATRIX_MR',
 'A nurse assesses five deteriorating clients. For each client, select every category of problem that the findings demonstrate. More than one category may apply.',
 'The airway, breathing and circulation framework is a sorting tool, and a client may occupy more than one category at once. Stridor after extubation is purely an airway and breathing problem. Hypotension with cool mottled skin is purely circulatory. A cardiac arrest involves all three simultaneously, which is why it outranks everything. A falling Glasgow Coma Scale score with snoring respirations is both neurological and an airway threat, because a depressed conscious level is the commonest cause of airway obstruction on a general ward.',
 '{"rows":[{"id":"r1","text":"A client with stridor and accessory muscle use after extubation"},{"id":"r2","text":"A client with a systolic blood pressure of 78 mmHg and cool mottled skin"},{"id":"r3","text":"A client who is unresponsive, apnoeic and pulseless"},{"id":"r4","text":"A client whose Glasgow Coma Scale score has fallen from 14 to 9 and who has snoring respirations"},{"id":"r5","text":"A client with new right-sided weakness and slurred speech, a patent airway and a blood pressure of 148/86 mmHg"}],"columns":[{"id":"c1","text":"Airway or breathing problem"},{"id":"c2","text":"Circulation problem"},{"id":"c3","text":"Neurological deterioration"}],"row_label":"Client"}'::jsonb,
 '{"cells":{"r1":["c1"],"r2":["c2"],"r3":["c1","c2","c3"],"r4":["c1","c3"],"r5":["c3"]},"feedback":{}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem',
 'Ordering frameworks', 'Applying ABC to deterioration',
 'Very hard', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_MMR_531052', 'MATRIX_MR',
 'A registered nurse plans the work of a team on a general ward. For each activity, select every team member who may carry it out. More than one may apply.',
 'Scope widens as the task becomes more standardised and the client more predictable, and narrows as judgement is required. Data collection and personal care on stable clients can be carried out by any member of the team. Reinforcing teaching and simple wound care sit within the registered and the licensed practical nurse roles. The initial assessment of a new client and the administration of blood components stay with the registered nurse, because both depend on assessment and evaluation that cannot be handed on.',
 '{"rows":[{"id":"r1","text":"Recording a routine blood pressure on a stable client"},{"id":"r2","text":"Performing the first assessment of a newly admitted client"},{"id":"r3","text":"Administering a unit of packed red cells"},{"id":"r4","text":"Reinforcing teaching about a low-salt diet that has already been given"},{"id":"r5","text":"Assisting a stable client with a bed bath"},{"id":"r6","text":"Changing a simple dry dressing on a healing wound"}],"columns":[{"id":"c1","text":"Registered nurse"},{"id":"c2","text":"Licensed practical nurse"},{"id":"c3","text":"Unlicensed assistive personnel"}],"row_label":"Activity"}'::jsonb,
 '{"cells":{"r1":["c1","c2","c3"],"r2":["c1"],"r3":["c1"],"r4":["c1","c2"],"r5":["c1","c2","c3"],"r6":["c1","c2"]},"feedback":{}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem',
 'Delegation', 'Scope of practice across the team',
 'Very hard', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_CLZ_531053', 'CLOZE',
 'Complete the statement about post-operative stability. A client who had surgery under general anaesthesia six hours ago is classified as {1}, whereas a client who had surgery under regional anaesthesia 30 hours ago and whose assessment is unchanged is classified as {2}.',
 'Two features decide post-operative stability: how long ago the surgery was and what kind of anaesthesia was used. General anaesthesia depresses airway reflexes, ventilation and blood pressure, and the first 12 hours is the window in which bleeding and airway problems appear, so a client inside that window is unstable regardless of the recorded observations. Beyond 12 hours, with a regional block that leaves the airway untouched and an unchanged assessment, the same client becomes stable.',
 '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"unstable"},{"id":"c2","text":"stable"}]},{"id":"b2","choices":[{"id":"c1","text":"unstable"},{"id":"c2","text":"stable"}]}]}'::jsonb,
 '{"answers":{"b1":"c1","b2":"c2"},"feedback":{}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem',
 'Prioritisation', 'Anaesthesia and the 12 hour window',
 'Easy', 'CURATOR_LABEL', 'Understand', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_CLZ_531054', 'CLOZE',
 'Complete the statement about triage at the scene of a multiple casualty incident. A casualty who walks unaided to the collection point is tagged {1}, and a casualty who remains apnoeic after the airway has been opened is tagged {2}.',
 'Walking demonstrates a patent airway, adequate perfusion and enough neurological function to follow an instruction, so ambulant casualties are tagged green and assessed later however dramatic their wounds appear. Persistent apnoea after the single permitted intervention of opening the airway carries a very low chance of survival, so the casualty is tagged black, or expectant. This is the reverse of hospital practice, where the same casualty would be the first priority of all.',
 '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"red"},{"id":"c2","text":"yellow"},{"id":"c3","text":"green"}]},{"id":"b2","choices":[{"id":"c1","text":"red"},{"id":"c2","text":"black"},{"id":"c3","text":"yellow"}]}]}'::jsonb,
 '{"answers":{"b1":"c3","b2":"c2"},"feedback":{}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem',
 'Disaster triage', 'Tag colours',
 'Very easy', 'CURATOR_LABEL', 'Remember', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728'),

('NCLEX_TF_531055', 'TF',
 'During a multiple casualty incident in which casualties greatly outnumber responders, a casualty who is pulseless and apnoeic after the airway has been opened should receive resuscitation before other casualties. Is this statement true or false?',
 'In everyday practice a pulseless, breathless client is the first priority and receives immediate resuscitation. In a multiple casualty incident the calculation reverses, because a single resuscitation attempt removes responders from a large number of casualties who could survive with brief intervention. The casualty is therefore tagged expectant and responders move on. The distinction is not about the value of the individual but about what the available resources can achieve.',
 '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb,
 '{"answer":"B","feedback":{"A":"Incorrect. Resuscitating one casualty in a mass casualty incident consumes responders needed by many salvageable casualties.","B":"Correct. In a mass casualty incident the pulseless, apnoeic casualty is tagged expectant and treated last, the reverse of in-hospital priority."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem',
 'Disaster triage', 'Contrast with in-hospital arrest',
 'Very easy', 'CURATOR_LABEL', 'Understand', '{}', 1, TRUE, TRUE, FALSE, FALSE,
 'gapfill-20260728');
